pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _newOwner) public {
        vm.assume(_newOwner != address(0));
        address admin = address(uint160(uint256(keccak256(abi.encodePacked("admin")))));
        vm.assume(_newOwner != admin);
        vm.startPrank(address(this));
        bool success;
        try c.setOwner(_newOwner) returns (bool res) {
            success = res;
        } catch {
            success = false;
        }
        vm.stopPrank();
        assertTrue(success);
    }
}
